sealed class LockedGameLoadContext:AssemblyLoadContext { private readonly string root; private readonly LoaderManifest manifest; private readonly List<LoadResolution> actual=new(); public LockedGameLoadContext(string root,LoaderManifest manifest):base("position-for-mine-entry-content-probe",true){this.root=root;this.manifest=manifest;} private static string? FileAt(string root,string relative){var file=Path.GetFullPath(Path.Combine(root,relative));return File.Exists(file)?file:null;} private static string HashAt(string file)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(file))).ToLowerInvariant(); private static AssemblyIdentity NameAt(AssemblyName name)=>new(name.Name??"",name.Version?.ToString()??"",name.CultureName??"",Convert.ToHexString(name.GetPublicKeyToken()??Array.Empty<byte>()).ToLowerInvariant()); public Assembly LoadVerified(SnapshotMember member){if(FrameworkPolicy.IsFrameworkAssembly(member.Identity))throw new InvalidOperationException("framework_snapshot_load_forbidden:"+member.Identity.DisplayName);var file=FileAt(root,member.RelativeFileName)??throw new InvalidOperationException("snapshot_member_missing");if(HashAt(file)!=member.Sha256||NameAt(AssemblyName.GetAssemblyName(file))!=member.Identity)throw new InvalidOperationException("snapshot_member_identity_or_hash_drift");var assembly=LoadFromAssemblyPath(file);Record(member.Identity,"snapshot");return assembly;} protected override Assembly? Load(AssemblyName requested){var identity=NameAt(requested);if(FrameworkPolicy.IsFrameworkAssembly(identity)){if(!FrameworkPolicy.TryResolveCompatibleFrameworkReference(identity,out var resolved)||!manifest.AllowedFrameworkFallbackIdentities.Contains(resolved))throw new FileLoadException("undeclared_or_incompatible_framework_runtime_fallback:"+identity.DisplayName);Record(resolved,"framework_default");return null;}var member=manifest.DeclaredSnapshotClosure.SingleOrDefault(x=>x.Identity==identity);if(member is not null)return LoadVerified(member);throw new FileLoadException("undeclared_or_identity_mismatched_assembly_request:"+identity.DisplayName);} private void Record(AssemblyIdentity identity,string source){if(!actual.Contains(new LoadResolution(identity,source),LoadResolutionComparer.Instance))actual.Add(new(identity,source));} public bool WasResolved(LoadResolution resolution)=>actual.Contains(resolution,LoadResolutionComparer.Instance); public LoadResolution[] ActualResolvedLoadSet()=>actual.OrderBy(x=>x.Identity.DisplayName,StringComparer.Ordinal).ThenBy(x=>x.Source,StringComparer.Ordinal).ToArray(); }
